import os
import queue
from typing import Callable, Iterable, List, Optional

import azure.cognitiveservices.speech as speechsdk


class StreamingSpeechToTextRecognizer:
    def __init__(
        self,
        language: str = "en-US",
        punctuation: bool = True,
        api_key: Optional[str] = None,
        region: Optional[str] = None,
        device_index: Optional[int] = None,
        sample_rate_hz: int = 16000,
        audio_format: speechsdk.audio.AudioStreamFormat = None,
    ):
        self.language = language
        self.punctuation = punctuation
        self.api_key = api_key or os.getenv("AZURE_SPEECH_KEY")
        self.region = region or os.getenv("AZURE_SPEECH_REGION")
        if not self.api_key or not self.region:
            raise ValueError("AZURE_SPEECH_KEY and AZURE_SPEECH_REGION must be set or provided")

        self.sample_rate_hz = sample_rate_hz
        self.audio_format = audio_format or speechsdk.audio.AudioStreamFormat(
            samples_per_second=sample_rate_hz, bits_per_sample=16, channels=1
        )

        self.speech_config = speechsdk.SpeechConfig(subscription=self.api_key, region=self.region)
        self.speech_config.speech_recognition_language = self.language
        if self.punctuation:
            self.speech_config.set_property(
                speechsdk.PropertyId.SpeechServiceConnection_InitialSilenceTimeoutMs, "5000"
            )
            self.speech_config.set_service_property(
                "punctuation", "true", speechsdk.ServicePropertyChannel.UriQueryParameter
            )

        self.push_stream = speechsdk.audio.PushAudioInputStream(self.audio_format)
        self.audio_config = speechsdk.audio.AudioConfig(stream=self.push_stream)
        self.recognizer = speechsdk.SpeechRecognizer(
            speech_config=self.speech_config,
            audio_config=self.audio_config,
        )

        self._final_results: List[str] = []
        self._partial_results: List[str] = []
        self._done = False
        self._error: Optional[Exception] = None
        self._queue: "queue.Queue[Optional[str]]" = queue.Queue()

        self.recognizer.recognized.connect(self._on_recognized)
        self.recognizer.recognizing.connect(self._on_recognizing)
        self.recognizer.canceled.connect(self._on_canceled)
        self.recognizer.session_stopped.connect(self._on_session_stopped)

    def _on_recognizing(self, evt: speechsdk.SpeechRecognitionEventArgs) -> None:
        text = evt.result.text.strip()
        if text:
            self._partial_results.append(text)
            self._queue.put(text)

    def _on_recognized(self, evt: speechsdk.SpeechRecognitionEventArgs) -> None:
        text = evt.result.text.strip()
        if text:
            self._final_results.append(text)
            self._queue.put(text)

    def _on_canceled(self, evt: speechsdk.SpeechRecognitionCanceledEventArgs) -> None:
        self._error = RuntimeError(
            f"Recognition canceled: reason={evt.reason}, error_details={getattr(evt, 'error_details', '')}"
        )
        self._done = True
        self._queue.put(None)

    def _on_session_stopped(self, evt: speechsdk.SessionEventArgs) -> None:
        self._done = True
        self._queue.put(None)

    def start(self) -> None:
        self.recognizer.start_continuous_recognition()

    def stop(self) -> None:
        self.recognizer.stop_continuous_recognition()
        self._done = True
        self._queue.put(None)

    def feed_audio(self, pcm16_mono_bytes: bytes) -> None:
        if not pcm16_mono_bytes:
            return
        self.push_stream.write(pcm16_mono_bytes)

    def close_input(self) -> None:
        self.push_stream.close()

    def transcribe_stream(
        self,
        audio_chunks: Iterable[bytes],
        on_partial: Optional[Callable[[str], None]] = None,
        on_final: Optional[Callable[[str], None]] = None,
    ) -> List[str]:
        self.start()
        try:
            for chunk in audio_chunks:
                if chunk:
                    self.feed_audio(chunk)

            self.close_input()

            while not self._done:
                item = self._queue.get()
                if item is None:
                    break
                if item and on_partial:
                    on_partial(item)

            if self._error:
                raise self._error

            if on_final:
                for text in self._final_results:
                    on_final(text)

            return self._final_results
        finally:
            try:
                self.stop()
            except Exception:
                pass


def start_streaming_recognizer(
    language: str = "en-US",
    punctuation: bool = True,
) -> StreamingSpeechToTextRecognizer:
    return StreamingSpeechToTextRecognizer(language=language, punctuation=punctuation)
